import { useEditor, EditorContent } from "@tiptap/react";
import StarterKit from "@tiptap/starter-kit";
import * as Y from "yjs";

export function Editor() {
  const ydoc = new Y.Doc();
  const editor = useEditor({ extensions: [StarterKit] });
  return EditorContent(editor);
}
EOF
git add -A && git -c user.email=t@t -c user.name=t commit -qm init
echo "=== IMPORTS ==="
"$HOME/.local/bin/entire" graph edges --repo "$TMP" --relation IMPORTS --format ndjson | head -5
echo "=== CALLS/CONSTRUCTS ==="
"$HOME/.local/bin/entire" graph edges --repo "$TMP" --relation CALLS,CONSTRUCTS --format ndjson | head -6
rm -rf "$TMP"

