301	    steps.push({
302	      name,
303	      freq: `${set.size}/${total}`,
304	      level: set.size >= Math.ceil(total / 2) ? "high" : "warn",
305	      code: symSnippet.get(name) || `${name}(…)`,
306	      note: `A ${library} API used across ${set.size}/${total} mined repos.`,
307	      receipts,
308	    });
309	  }
